// frontend/src/components/Services.jsx
import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom'; // <-- Added useLocation

const Services = () => {
    const [menuOpen, setMenuOpen] = useState(false);
    const navigate = useNavigate();
    const location = useLocation(); // <-- Get current URL

    // Hardcoded data - you will fetch this from MongoDB later!
    const services = [
        { 
            id: 1, 
            title: "Soin visage", 
            duration: "1h", 
            price: "3000 DA", 
            image: "/Soin%20visage.jpeg" 
        },
        { 
            id: 2, 
            title: "Massage relaxant", 
            duration: "1h30min", 
            price: "4000 DA", 
            image: "/Massagerelaxant.jpeg" 
        },
        { 
            id: 3, 
            title: "Coiffure femme", 
            duration: "2h", 
            price: "3000 DA", 
            image: "/Coiffure%20femme.jpg" 
        },
        { 
            id: 4, 
            title: "Coloration cheveux", 
            duration: "3h", 
            price: "6000 DA", 
            image: "/Coloration%20cheveux.jpg" 
        },
        { 
            id: 5, 
            title: "Pédicure", 
            duration: "1h", 
            price: "2000 DA", 
            image: "/Pédicure.jpg" 
        },
        { 
            id: 6, 
            title: "Épilation", 
            duration: "1h", 
            price: "3000 DA", 
            image: "/Épilation.webp" 
        },
    ];

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/login');
    };

    const toggleMenu = () => {
        setMenuOpen(!menuOpen);
    };

    // Helper to check if the current link is active
    const isActive = (path) => location.pathname === path;

    return (
        <div className="services-page">
            {/* ---------------- NAVBAR ---------------- */}
            <nav className="services-navbar">
                <div className="nav-logo">BeautyBook</div>

                {/* Hamburger Menu (Only visible on mobile) */}
                <div className="hamburger" onClick={toggleMenu}>
                    ☰
                </div>

                {/* Desktop Links */}
                <div className="nav-links desktop-nav">
                    {/* If on /services, add "active" class. Otherwise stays black */}
                    <span 
                        className={`nav-item ${isActive('/services') ? 'active' : ''}`}
                    >
                        🌸 Beauty treatments
                    </span>

                    <span 
                        className={`nav-item ${isActive('/appointments') ? 'active' : ''}`}
                        onClick={() => navigate('/appointments')}
                    >
                        📅 Appointment
                    </span>

                    <span className="nav-icon">🔔</span>
                    <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                </div>
            </nav>

            {/* ---------------- MOBILE MENU (Hidden by default) ---------------- */}
            <div className={`mobile-menu ${menuOpen ? 'open' : ''}`}>
                <div className="mobile-menu-content">
                    {/* Mobile active detection */}
                    <span className={`mobile-nav-item ${isActive('/services') ? 'active' : ''}`}>
                        🌸 Beauty treatments
                    </span>
                    <span 
                        className={`mobile-nav-item ${isActive('/appointments') ? 'active' : ''}`}
                        onClick={() => { setMenuOpen(false); navigate('/appointments'); }}
                    >
                        📅 Appointment
                    </span>
                    <div className="mobile-nav-icons">
                        <span className="nav-icon">🔔</span>
                        <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                    </div>
                </div>
            </div>

            {/* ---------------- GRID OF SERVICES ---------------- */}
            <div className="services-grid-container">
                <div className="services-grid">
                    {services.map((service) => (
                        <div key={service.id} className="service-card">
                            <div className="service-image-wrapper">
                                <img src={service.image} alt={service.title} className="service-image" />
                            </div>
                            <h3 className="service-title">{service.title}</h3>
                            <div className="service-details">
                                <span>Durée: {service.duration}</span>
                                <span>Prix: {service.price}</span>
                            </div>
                            <button className="service-btn">Add to appointment</button>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Services;
